/* Fade in and rise 15px while the box enters the window, tied to the scroll: done after the
   first 220px of entry, so anything starting in the first screen is already shown. Each
   stagger step starts 40px later. The step comes in as --arc-reveal-step. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .arc-reveal {
      animation: arc-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--arc-reveal-step, 0) * 40px) entry calc(220px + var(--arc-reveal-step, 0) * 40px);
    }
  }
}

@keyframes arc-reveal-rise {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: none; }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./arc-reveal.css";

export interface ArcRevealProps {
  children: ReactNode;
  /** stagger position in a row (0, 1, 2…): each step starts the fade 40px of scroll later */
  step?: number;
  className?: string;
}

/** Wraps anything that should fade in and rise 15px as it scrolls into view (CSS only). */
export function ArcReveal({ children, step = 0, className }: ArcRevealProps) {
  return (
    <div className={cn("arc-reveal", className)} style={{ "--arc-reveal-step": step } as CSSProperties}>
      {children}
    </div>
  );
}
